-- The schema as it was when Flyway was added: generated by Hibernate from the entities on an empty PostgreSQL
-- database (ddl-auto=create), then tidied by hand. Databases that already existed then (built by ddl-auto=update)
-- are baselined at this version instead of running it (spring.flyway.baseline-on-migrate); V2 brings them in line.
--
-- Primary key, unique and check constraints use PostgreSQL's default names (recipes_pkey, users_email_key,
-- recipes_visibility_check); foreign keys keep the names Hibernate gives them, which older databases have too.

-- Users and families ---------------------------------------------------------------------------------------------

CREATE TABLE users (
    id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at    timestamp(6) NOT NULL,
    updated_at    timestamp(6) NOT NULL,
    is_active     boolean NOT NULL,
    email         varchar(255) NOT NULL UNIQUE,
    password_hash varchar(100) NOT NULL,
    first_name    varchar(100) NOT NULL,
    last_name     varchar(100) NOT NULL,
    date_of_birth date NOT NULL
);

CREATE TABLE families (
    id                     bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at             timestamp(6) NOT NULL,
    updated_at             timestamp(6) NOT NULL,
    is_active              boolean NOT NULL,
    name                   varchar(100) NOT NULL,
    invite_code            varchar(8) UNIQUE,
    invite_code_created_at timestamp(6)
);

CREATE TABLE family_members (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at timestamp(6) NOT NULL,
    updated_at timestamp(6) NOT NULL,
    is_active  boolean NOT NULL,
    family_id  bigint NOT NULL,
    user_id    bigint NOT NULL,
    role       varchar(20) NOT NULL CHECK (role IN ('OWNER', 'MEMBER')),
    CONSTRAINT uk_family_members_user UNIQUE (user_id)
);

-- Recipes --------------------------------------------------------------------------------------------------------

CREATE TABLE recipes (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at         timestamp(6) NOT NULL,
    updated_at         timestamp(6) NOT NULL,
    is_active          boolean NOT NULL,
    title              varchar(255) NOT NULL,
    description        text,
    servings           integer,
    prep_time_minutes  integer,
    cook_time_minutes  integer,
    total_time_minutes integer,
    source_url         varchar(255),
    created_by_user_id bigint,
    visibility         varchar(10) DEFAULT 'PUBLIC' NOT NULL CHECK (visibility IN ('PUBLIC', 'PRIVATE'))
);

CREATE TABLE steps (
    id                     bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at             timestamp(6) NOT NULL,
    updated_at             timestamp(6) NOT NULL,
    is_active              boolean NOT NULL,
    recipe_id              bigint NOT NULL,
    step_order             integer NOT NULL,
    instruction_text       text NOT NULL,
    estimated_time_minutes integer,
    raw_string             varchar(255)
);

-- The units of the Unit enum. Adding a unit to the enum needs a migration that replaces these checks.
CREATE TABLE ingredients (
    id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at       timestamp(6) NOT NULL,
    updated_at       timestamp(6) NOT NULL,
    is_active        boolean NOT NULL,
    recipe_id        bigint NOT NULL,
    name             varchar(255) NOT NULL,
    quantity         numeric(10, 3) NOT NULL,
    unit             varchar(255) NOT NULL CHECK (unit IN (
                         'TEASPOON', 'TABLESPOON', 'CUP', 'FLUID_OUNCE', 'PINT', 'QUART', 'GALLON', 'MILLILITER', 'LITER',
                         'OUNCE', 'POUND', 'GRAM', 'KILOGRAM',
                         'CAN', 'JAR', 'BOTTLE', 'PACKAGE', 'BAG', 'BOX', 'CONTAINER',
                         'EACH', 'PINCH', 'DASH', 'CLOVE', 'SLICE', 'HEAD', 'BUNCH')),
    package_quantity numeric(10, 3),
    package_unit     varchar(255) CHECK (package_unit IN (
                         'TEASPOON', 'TABLESPOON', 'CUP', 'FLUID_OUNCE', 'PINT', 'QUART', 'GALLON', 'MILLILITER', 'LITER',
                         'OUNCE', 'POUND', 'GRAM', 'KILOGRAM',
                         'CAN', 'JAR', 'BOTTLE', 'PACKAGE', 'BAG', 'BOX', 'CONTAINER',
                         'EACH', 'PINCH', 'DASH', 'CLOVE', 'SLICE', 'HEAD', 'BUNCH'))
);

CREATE TABLE recipe_categories (
    recipe_id bigint NOT NULL,
    category  varchar(255)
);

CREATE TABLE recipe_equipment (
    recipe_id bigint NOT NULL,
    equipment varchar(255)
);

-- Meal plans -----------------------------------------------------------------------------------------------------

CREATE TABLE meal_plans (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at         timestamp(6) NOT NULL,
    updated_at         timestamp(6) NOT NULL,
    is_active          boolean NOT NULL,
    name               varchar(100),
    start_date         date NOT NULL,
    number_of_days     integer NOT NULL,
    created_by_user_id bigint
);

CREATE TABLE meal_plan_meal_types (
    meal_plan_id bigint NOT NULL,
    meal_type    varchar(20) NOT NULL CHECK (meal_type IN ('BREAKFAST', 'LUNCH', 'SNACK', 'DINNER')),
    PRIMARY KEY (meal_plan_id, meal_type)
);

CREATE TABLE meal_plan_entries (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at   timestamp(6) NOT NULL,
    updated_at   timestamp(6) NOT NULL,
    is_active    boolean NOT NULL,
    meal_plan_id bigint NOT NULL,
    entry_date   date NOT NULL,
    meal_type    varchar(20) NOT NULL CHECK (meal_type IN ('BREAKFAST', 'LUNCH', 'SNACK', 'DINNER')),
    recipe_id    bigint NOT NULL,
    CONSTRAINT uk_meal_plan_entries_slot UNIQUE (meal_plan_id, entry_date, meal_type)
);

-- A family's (or, without a family, a user's) "exclude from meal plans" list.
CREATE TABLE meal_plan_exclusions (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at timestamp(6) NOT NULL,
    updated_at timestamp(6) NOT NULL,
    is_active  boolean NOT NULL,
    recipe_id  bigint NOT NULL,
    family_id  bigint,
    user_id    bigint,
    CONSTRAINT uk_meal_plan_exclusions_family UNIQUE (family_id, recipe_id),
    CONSTRAINT uk_meal_plan_exclusions_user UNIQUE (user_id, recipe_id)
);

-- Shopping lists -------------------------------------------------------------------------------------------------

CREATE TABLE shopping_lists (
    id                   bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at           timestamp(6) NOT NULL,
    updated_at           timestamp(6) NOT NULL,
    is_active            boolean NOT NULL,
    meal_plan_id         bigint NOT NULL UNIQUE,
    generated_at         timestamp(6) NOT NULL,
    generated_by_user_id bigint
);

CREATE TABLE shopping_list_left_out (
    shopping_list_id bigint NOT NULL,
    "position"       integer NOT NULL,
    recipe_title     varchar(255) NOT NULL,
    PRIMARY KEY ("position", shopping_list_id)
);

CREATE TABLE shopping_list_items (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at         timestamp(6) NOT NULL,
    updated_at         timestamp(6) NOT NULL,
    is_active          boolean NOT NULL,
    shopping_list_id   bigint NOT NULL,
    item_key           varchar(400) NOT NULL,
    name               varchar(255) NOT NULL,
    quantity           numeric(12, 3),
    unit               varchar(20) CHECK (unit IN (
                           'TEASPOON', 'TABLESPOON', 'CUP', 'FLUID_OUNCE', 'PINT', 'QUART', 'GALLON', 'MILLILITER', 'LITER',
                           'OUNCE', 'POUND', 'GRAM', 'KILOGRAM',
                           'CAN', 'JAR', 'BOTTLE', 'PACKAGE', 'BAG', 'BOX', 'CONTAINER',
                           'EACH', 'PINCH', 'DASH', 'CLOVE', 'SLICE', 'HEAD', 'BUNCH')),
    package_quantity   numeric(10, 3),
    package_unit       varchar(20) CHECK (package_unit IN (
                           'TEASPOON', 'TABLESPOON', 'CUP', 'FLUID_OUNCE', 'PINT', 'QUART', 'GALLON', 'MILLILITER', 'LITER',
                           'OUNCE', 'POUND', 'GRAM', 'KILOGRAM',
                           'CAN', 'JAR', 'BOTTLE', 'PACKAGE', 'BAG', 'BOX', 'CONTAINER',
                           'EACH', 'PINCH', 'DASH', 'CLOVE', 'SLICE', 'HEAD', 'BUNCH')),
    recipes            text,
    sort_order         integer NOT NULL,
    checked            boolean NOT NULL,
    checked_by_user_id bigint,
    checked_at         timestamp(6)
);

